const transitions = {
  idle:    { start: "running" },
  running: { pause: "paused", stop: "idle" },
  paused:  { start: "running", stop: "idle" },
};
export function send(machine, event) {
  const next = transitions[machine.state]?.[event];
  if (!next) throw new Error(`invalid transition: ${machine.state} -> ${event}`);
  machine.state = next;
}
